mapper.select:
SELECT r.id, r.declaration_id, d.declaration_no, d.taxpayer_name_snapshot AS taxpayer_name, d.declaration_type_snapshot AS declaration_type_name, r.review_action AS action, r.review_comment AS comment, r.reviewer_id, u.display_name AS reviewer_name, r.from_status, r.to_status, r.reviewed_at FROM declaration_review r JOIN tax_declaration d ON d.id = r.declaration_id JOIN sys_user u ON u.id = r.reviewer_id
AND r.reviewer_id = #{reviewerId}
AND r.review_action = #{action}
AND r.reviewed_at >= #{from}
AND r.reviewed_at <= #{to}
AND (d.declaration_no LIKE CONCAT('%', #{keyword}, '%') OR d.taxpayer_name_snapshot LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.reviewed_at DESC, r.id DESC
